agent-librarian.code:
// Helps readers find books.
agent Librarian(tools: BookTools)
  prompt: string = "You help readers find books. Use the tools; never invent ids."

graph-summary.code:
state SummaryState
  question: string
  answer: string

@state(SummaryState)
graph Summary(librarian: Librarian)
  @start
  ask(state: SummaryState) <string, string>
    { "answer": ~librarian.ask(state.question) }

graph-two-steps.code:
// State of the review graph.
state ReviewState
  text: string
  draft: string
  final: string

// Drafts an answer and then shortens it.
@state(ReviewState)
graph Review(librarian: Librarian)
  @start
  @next("polish")
  draft(state: ReviewState) ReviewState
    state.draft = ~librarian.ask(state.text)
    state

  polish(state: ReviewState) ReviewState
    state.final = ~librarian.ask("Shorten: ${state.draft}")
    state

