// file: components/books/data/entities/book.nuc
@entity("books")
entity Book()
  @primary(generated = true)
  id: int
  title: string
  author: string

// file: components/books/data/repositories/book_repository.nuc
repository BookRepository
  byAuthor(author: string) Book[]
    where({ "author": author })
    orderBy("title")
    getMany()

// file: components/books/domain/usecases/books_of_author.nuc
usecase BooksOfAuthor(books: BookRepository)
  exec(author: string) Result<Error, Book[]>
    Ok(~books.byAuthor(author))

// file: components/books/books_app_component.nuc
appcomponent BooksAppComponent
  booksOf() = BooksOfAuthor.exec

// file: components/books/api/books_controller.nuc
@controller("books")
controller BooksController(books: BooksAppComponent)
  @get("author/{author}")
  byAuthor(author: string) Result<Error, Book[]>
    ~books.booksOf(author)

